/* ============================================================
   MODELES 3D
   ============================================================ */

const th = i => {

  if (i.img) {

    return `
      <img
        class="thumbimg"
        src="${i.img}"
        alt="${i.n}"
      >
    `;

  }

  return `
    <div class="thumb"></div>
  `;
};


const models = [

  {
    n: "Switch 1 (2017)",

    d: "Ajouté le 30/09/2026",

    img: "data:image/jpeg;base64,",

    shots: ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"],

    file: "",

    fname: ""
  },

  

];


/* ============================================================
   CONFIGURATION DU SITE
   ============================================================ */

