/* ============================================================
   PROJETS
   ============================================================ */

/*
   Image du projet.
   Chaque image est automatiquement en 64x64
   grâce au CSS.
*/

const iimg = i => {

  if (i.img) {

    return `
      <img
        class="itemimg"
        src="${i.img}"
        alt="${i.n}"
        width="64"
        height="64"
      >
    `;

  }

  return `
    <div
      class="itemimg placeholder"
      aria-hidden="true"
    ></div>
  `;
};


/*
   Création d'un projet.

   Résultat :

   [ IMAGE 64x64 ] [ TITRE
                     DESCRIPTION ]
*/

const item = i => {

  const content = `

    ${iimg(i)}

    <div class="itemcontent">

      <h3>
        ${i.n}
      </h3>

      <p>
        ${i.d}
      </p>

    </div>

  `;


  /*
     Projet avec lien
  */

  if (i.url) {

    return `
      <a
        class="item link"
        href="${i.url}"
        target="_blank"
        rel="noopener"
      >
        ${content}
      </a>
    `;

  }


  /*
     Projet sans lien
  */

  return `
    <div class="item">
      ${content}
    </div>
  `;
};


/* ============================================================
   CARTES MODELES 3D
   ============================================================ */

const mcard = (i, k) => {

  return `

    <div
      class="card click"
      data-i="${k}"
    >

      ${th(i)}

      <div class="t">

        <h3>
          ${i.n}
        </h3>

        <p>
          ${i.d}
        </p>

      </div>

      <div class="foot">

        <svg
          viewBox="0 0 24 24"
          width="26"
          height="26"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
          stroke-linejoin="round"
          stroke-linecap="round"
        >

          <path
            d="M12 2l9 5v10l-9 5-9-5V7z"
          />

          <path
            d="M3 7l9 5 9-5M12 12v10"
          />

        </svg>

      </div>

    </div>

  `;
};


/* ============================================================
   AFFICHAGE
   ============================================================ */

document.getElementById("pg").innerHTML =
  projects.map(item).join("");


document.getElementById("mg").innerHTML =
  models.map(mcard).join("");


/* ============================================================
   NAVIGATION
   ============================================================ */

const btns =
  document.querySelectorAll(".btn");


/*
   Cliquer sur le logo retourne à l'accueil
*/

document.querySelector(".logo").onclick = () => {

  btns[0].click();

};


/*
   Navigation
*/

btns.forEach(b => {

  b.onclick = () => {

    btns.forEach(x => {

      x.classList.toggle(
        "active",
        x === b
      );

    });


    const cur =
      document.querySelector("section.show");

    const next =
      document.getElementById(b.dataset.t);


    if (cur === next) {
      return;
    }


    cur.classList.remove("in");


    setTimeout(() => {

      cur.classList.remove("show");

      next.classList.add("show");

      void next.offsetWidth;

      next.classList.add("in");

    }, 300);

  };

});


/*
   Animation initiale
*/

document
  .getElementById("home")
  .classList.add("in");


/* ============================================================
   MODAL MODELES 3D
   ============================================================ */

const modal =
  document.getElementById("modal");

const mbox =
  document.getElementById("mbox");


/*
   Ouvrir un modèle
*/

function openModel(m) {

  const shots = (

    m.shots && m.shots.length

      ? m.shots.map(
          u =>
            `
              <img
                src="${u}"
                alt="Screenshot ${m.n}"
              >
            `
        )

      : [1, 2, 3].map(
          () =>
            `<div class="ph"></div>`
        )

  ).join("");


  mbox.innerHTML = `

    <button
      class="x"
      id="mx"
      aria-label="Fermer"
    >
      ×
    </button>

    <h2>
      ${m.n}
    </h2>

    <p>
      ${m.d}
    </p>

    <div class="shots">
      ${shots}
    </div>

    <button
      class="dl"
      id="dl"
    >
      ⬇ Download
    </button>

    <span
      class="msg"
      id="dmsg"
    ></span>

  `;


  /*
     Bouton fermer
  */

  document
    .getElementById("mx")
    .onclick = closeModal;


  /*
     Bouton téléchargement
  */

  document
    .getElementById("dl")
    .onclick = async () => {

      const msg =
        document.getElementById("dmsg");


      try {

        const dls =
          await claude.use("downloads");


        if (!dls) {

          msg.textContent =
            "Téléchargement indisponible ici.";

          return;
        }


        let data;
        let name;


        /*
           Fichier réel
        */

        if (m.file) {

          data =
            await (
              await fetch(m.file)
            ).blob();

          name =
            m.fname ||
            (m.n + ".zip");

        }


        /*
           Fichier de test
        */

        else {

          data =
            "Fichier de " +
            m.n +
            " : à remplacer par ton vrai fichier.";

          name =
            m.n +
            ".txt";
        }


        await dls.save({

          filename: name,

          data: data

        });


        msg.textContent = "";

      }


      catch (e) {

        msg.textContent =
          (
            e &&
            e.code === "declined"
          )
            ? ""
            : "Téléchargement impossible.";

      }

    };


  /*
     Afficher le popup
  */

  modal.classList.add("open");

}


/* ============================================================
   FERMETURE DU MODAL
   ============================================================ */

/*
   Fermer le popup
*/

function closeModal() {

  modal.classList.remove("open");

}


/*
   Cliquer sur le fond du popup
*/

modal.onclick = e => {

  if (e.target === modal) {

    closeModal();

  }

};


/*
   Touche Escape
*/

document.addEventListener(
  "keydown",
  e => {

    if (e.key === "Escape") {

      closeModal();

    }

  }
);


/* ============================================================
   CLIC SUR LES MODELES
   ============================================================ */

document
  .getElementById("mg")
  .onclick = e => {

    const c =
      e.target.closest(".card");


    if (c) {

      openModel(
        models[+c.dataset.i]
      );

    }

  };
